import { test, expect } from '@playwright/test'
import { loginAsDeveloperCompanyOnce } from '../fixtures/auth-helpers.js'
import {
  isSurveyChangePageResponse,
  isSurveyChangeHousePageResponse,
  isSurveyChangeDetailResponse
} from '../fixtures/presale-survey-change-helpers.js'

const VIEWPORTS = [
  { width: 1920, height: 950, tag: '1920' },
  { width: 1366, height: 800, tag: '1366' }
]

for (const vp of VIEWPORTS) {
  test.describe('bug6070 pagination @' + vp.tag, () => {
    test.use({ viewport: { width: vp.width, height: vp.height } })
    test.setTimeout(180000)

    test('pagination not clipped', async ({ page }) => {
      await loginAsDeveloperCompanyOnce(page)

      const listResponse = page.waitForResponse(isSurveyChangePageResponse, { timeout: 30000 })
      await page.evaluate(() => {
        window.location.hash = '#/ysxkxsba/surveyChange'
      })
      await listResponse
      const listBody = await (await listResponse).json()
      if (listBody.code !== 200) {
        test.skip(true, 'page api not ok: ' + listBody.msg)
        return
      }

      const listRoot = page.getByTestId('survey-change-record-list')
      await expect(listRoot).toBeVisible({ timeout: 20000 })

      // 用 CSS 定位带「查看」按钮的行，避免 getByRole 名称匹配（构建后按钮文字可能带图标）
      const viewButtons = listRoot.locator('.el-table__body-wrapper tbody tr td button', {
        hasText: '查看'
      })
      await expect(viewButtons.first()).toBeVisible({ timeout: 30000 })
      const btnCount = await viewButtons.count()

      let houseRows = 0
      for (let i = 0; i < btnCount; i++) {
        const backToList = async () => {
          const r = page.waitForResponse(isSurveyChangePageResponse, { timeout: 30000 })
          await page.evaluate(() => {
            window.location.hash = '#/ysxkxsba/surveyChange'
          })
          await r
          await expect(listRoot).toBeVisible({ timeout: 20000 })
          await expect(viewButtons.first()).toBeVisible({ timeout: 30000 })
        }

        if (i > 0) await backToList()

        const detailPromise = page.waitForResponse(isSurveyChangeDetailResponse, { timeout: 60000 })
        const housePromise = page
          .waitForResponse(isSurveyChangeHousePageResponse, { timeout: 20000 })
          .catch(() => null)
        await viewButtons.nth(i).click()
        await detailPromise
        await expect(page.getByTestId('survey-change-detail')).toBeVisible({ timeout: 20000 })
        const houseRes = await housePromise
        if (houseRes) {
          const body = await houseRes.json().catch(() => ({}))
          if (body.code === 200 && (body.rows || []).length > 0) {
            houseRows = body.rows.length
            break
          }
        }
      }

      if (!houseRows) {
        test.skip(true, 'no record with house rows')
        return
      }

      await page.getByTestId('survey-change-house-table').scrollIntoViewIfNeeded()
      const pagination = page
        .locator('.detail-container .collapse-container .pagination-container')
        .first()
      await expect(pagination).toBeVisible({ timeout: 20000 })

      const detailBox = await page.getByTestId('survey-change-detail').boundingBox()
      const pagBox = await pagination.boundingBox()
      const detailRight = Math.ceil(detailBox.x + detailBox.width)
      const pagRight = Math.round(pagBox.x + pagBox.width)
      expect(pagRight, 'pagRight=' + pagRight + ' detailRight=' + detailRight).toBeLessThanOrEqual(
        detailRight + 1
      )

      for (const sel of ['.el-pagination__sizes', '.el-pagination__jump']) {
        const loc = pagination.locator(sel)
        if (await loc.count()) {
          const box = await loc.first().boundingBox()
          if (box) {
            expect(Math.round(box.x + box.width), sel + ' beyond viewport').toBeLessThanOrEqual(
              vp.width + 1
            )
          }
        }
      }

      await page.screenshot({ path: 'e2e/output/bug6070/detail-' + vp.tag + '.png' })
      await pagination.screenshot({ path: 'e2e/output/bug6070/pagination-' + vp.tag + '.png' }).catch(() => {})
    })
  })
}

